  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('r', 0)).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
