import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('start, unknown run, duplicate start', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('bad task numbers and bad moves are refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [3, -1, 1.5]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('completes only when all complete', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskStarted('r', t), ok);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
});

test('eviction, requeue, failure', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  for (const t of [0, 1, 2]) await h.taskEvicted('r', t);
  assert.equal((await h.run('r'))!.status, 'evicted');
  await h.taskRequeued('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskRequeued('r', 1);
  await h.taskRequeued('r', 2);
  assert.equal((await h.run('r'))!.status, 'queued');
  await h.taskStarted('r', 1);
  assert.deepEqual(await h.taskFailed('r', 1), ok);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  // a failed run still takes commands
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'running', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  assert.deepEqual(await h.taskRetried('r', 1), ok);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'running', task1: 'queued', task2: 'queued' });
});

test('retry after all failed, and after cancel with a failed task', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  for (const t of [0, 1, 2]) await h.taskFailed('r', t);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.cancel('r')).ok, false);
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskRetried('r', t), ok);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });

  await h.start('s');
  await h.taskStarted('s', 0);
  await h.taskFailed('s', 0);
  assert.deepEqual(await h.cancel('s'), ok);
  assert.deepEqual(await h.run('s'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
  assert.deepEqual(await h.taskRetried('s', 0), ok);
  assert.equal((await h.run('s'))!.status, 'running');
  await h.taskStarted('s', 0);
  await h.taskCompleted('s', 0);
  assert.deepEqual(await h.run('s'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskRetried('s', 0)).ok, false);
});

test('failed task then the others complete: still failed until retried', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  await h.taskFailed('r', 0);
  await h.taskCompleted('r', 1);
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'failed');
  await h.taskRetried('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
});

test('cancel one task', async () => {
  const h = await createHost();
  await h.start('r');
  assert.deepEqual(await h.cancelTask('r', 0), ok);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  assert.equal((await h.cancelTask('r', 3)).ok, false);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancelTask('r', 1), ok);
  await h.taskStarted('r', 2);
  await h.taskFailed('r', 2);
  assert.equal((await h.cancelTask('r', 2)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'cancelled', task1: 'cancelled', task2: 'failed' });
  await h.taskRetried('r', 2);
  assert.deepEqual(await h.cancelTask('r', 2), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskRetried('r', 2)).ok, false);

  await h.start('s');
  for (const t of [0, 1, 2]) await h.taskStarted('s', t);
  await h.taskCompleted('s', 0);
  await h.taskCompleted('s', 1);
  assert.deepEqual(await h.cancelTask('s', 2), ok);
  assert.deepEqual(await h.run('s'), { status: 'cancelled', task0: 'completed', task1: 'completed', task2: 'cancelled' });
  assert.equal((await h.cancel('s')).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
