  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancelTask('r', 1), ok);
  await h.taskStarted('r', 2);
  await h.taskFailed('r', 2);
  assert.equal((await h.cancelTask('r', 2)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'cancelled', task1: 'cancelled', task2: 'failed', paused: false });
  await h.taskRetried('r', 2);
  assert.deepEqual(await h.cancelTask('r', 2), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: false });
  assert.equal((await h.taskRetried('r', 2)).ok, false);

  await h.start('s');
  for (const t of [0, 1, 2]) await h.taskStarted('s', t);
  await h.taskCompleted('s', 0);
  await h.taskCompleted('s', 1);
  assert.deepEqual(await h.cancelTask('s', 2), ok);
  assert.deepEqual(await h.run('s'), { status: 'cancelled', task0: 'completed', task1: 'completed', task2: 'cancelled', paused: false });
  assert.equal((await h.cancel('s')).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled', paused: false });
  assert.equal((await h.start('r')).ok, false);
});
